public class SumCalculator {
    public static void main(String[] args) {
        int a = 3, b = 7;
        int num;

        num = sumOfTwoInt(a, b);
        System.out.println("The sum of 3 and 7 is " + num);
    }

    // a static method that sums two integers
    public static int sumOfTwoInt(int x, int y) {
        int sum;
        sum = x + y;
        return sum;
    }
}

