public static void displayMessage() {
    System.out.println("This is an example void function that will display when invoked.");
}

public static void displayInfo(String fname, String lname, int age) {
    System.out.println("Student Information:");
    System.out.println("First Name: " + fname);
    System.out.println("Last Name: " + lname);
    System.out.println("Age: " + age);
}

public class VoidExamples {
    public static void main(String[] args) {
        // a non-static method must be called on an object
        VoidExamples msg = new VoidExamples();
        msg.displayMessage();

        // a static method is called directly
        displayInfo("Jess", "Diaz", 19);
    }

    // a non-static method with an empty parameter list
    public void displayMessage() {
        System.out.println("This is an example void function that will display when invoked.");
    }

    // a static method with a parameter list
    public static void displayInfo(String fname, String lname, int age) {
        System.out.println("Student Information:");
        System.out.println("First Name: " + fname);
        System.out.println("Last Name: " + lname);
        System.out.println("Age: " + age);
    }
}

public static int square(int n) {
    return n * n;
}

public static int sumOfSquares(int a, int b) {
    return square(a) + square(b);
}

// sumOfSquares(3, 4) returns 25

public static int add(int a, int b) {
    return a + b;
}

public static double add(double a, double b) {
    return a + b;
}

System.out.println(add(2, 3));       // 5
System.out.println(add(2.5, 3.5));   // 6.0
